            rule_section(:scores, "\u041A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438",
              "\u0414\u043B\u044F \u043F\u0430\u0440\u044B, \u0434\u0432\u0443\u0445 \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0430\u0440, \u0442\u0440\u043E\u0439\u043A\u0438 \u0438 \u043A\u0430\u0440\u0435 \u0441\u043B\u043E\u0436\u0438\u0442\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u043A\u0443\u0431\u0438\u043A\u043E\u0432, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0438\u0445 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u044E. \u041C\u0430\u043B\u044B\u0439 \u0441\u0442\u0440\u0438\u0442 \u0441\u043E\u0441\u0442\u043E\u0438\u0442 \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0447\u0438\u0441\u0435\u043B, \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u2014 \u0438\u0437 \u043F\u044F\u0442\u0438. \u0421\u043B\u043E\u0436\u0438\u0442\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432 \u0441\u0442\u0440\u0438\u0442\u0435. \u0424\u0443\u043B\u043B-\u0445\u0430\u0443\u0441 \u2014 \u044D\u0442\u043E \u0442\u0440\u043E\u0439\u043A\u0430 \u0438 \u043F\u0430\u0440\u0430. \u0414\u043B\u044F \u0444\u0443\u043B\u043B-\u0445\u0430\u0443\u0441\u0430, \u043F\u044F\u0442\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0438 \u0448\u0430\u043D\u0441\u0430 \u0441\u043B\u043E\u0436\u0438\u0442\u0435 \u0432\u0441\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F. \u0412 \u0448\u0430\u043D\u0441 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u043B\u044E\u0431\u043E\u0439 \u0431\u0440\u043E\u0441\u043E\u043A."),
            rule_section(:school, "\u0428\u043A\u043E\u043B\u0430 \u0438 \u0440\u0435\u0437\u0435\u0440\u0432",
              "\u0412 \u0448\u043A\u043E\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044E \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0441\u0432\u043E\u044F \u0441\u0442\u0440\u043E\u043A\u0430. \u0414\u043B\u044F \u0437\u0430\u043F\u0438\u0441\u0438 \u043D\u0443\u0436\u043D\u044B \u0442\u0440\u0438 \u043A\u0443\u0431\u0438\u043A\u0430 \u0441 \u044D\u0442\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C. \u0427\u0435\u0442\u044B\u0440\u0435 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0438 \u0434\u0430\u044E\u0442 24 \u043E\u0447\u043A\u0430 \u0438 \u043E\u0434\u043D\u0443 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0443 \u0432 \u0440\u0435\u0437\u0435\u0440\u0432. \u0415\u0441\u043B\u0438 \u043F\u043E\u0437\u0436\u0435 \u0432\u044B\u043F\u0430\u0434\u0443\u0442 \u0434\u0432\u0435 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0438, \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u0442\u0440\u0435\u0442\u044C\u044E \u0438\u0437 \u0440\u0435\u0437\u0435\u0440\u0432\u0430 \u0438 \u0437\u0430\u043F\u0438\u0448\u0438\u0442\u0435 12 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0432\u044B\u043F\u0430\u0432\u0448\u0438\u0435 \u043A\u0443\u0431\u0438\u043A\u0438."),
            rule_section(:bonuses, "\u041F\u0440\u0435\u043C\u0438\u0438",
              "\u041A\u0442\u043E \u043F\u0435\u0440\u0432\u044B\u043C \u0437\u0430\u043F\u043E\u043B\u043D\u0438\u0442 \u0441\u0442\u0440\u043E\u043A\u0443 \u0431\u0435\u0437 \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0439, \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u0440\u0435\u043C\u0438\u044E \u0432 \u0440\u0430\u0437\u043C\u0435\u0440\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0437\u0430\u043F\u0438\u0441\u0438. \u0417\u0430 \u043F\u0435\u0440\u0432\u044B\u0439 \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u0431\u0435\u0437 \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0439 \u0441\u0442\u043E\u043B\u0431\u0435\u0446 \u0434\u0430\u044E\u0442 60 \u043E\u0447\u043A\u043E\u0432. \u0417\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0432 \u0448\u043A\u043E\u043B\u0435 \u043B\u0438\u0448\u0430\u0435\u0442 \u0443\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u044B\u0445 \u043F\u0440\u0435\u043C\u0438\u0439."),
            rule_section(:options, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
              "\u041F\u0440\u0438 \u043E\u0434\u043D\u043E\u043C \u0438\u043B\u0438 \u0434\u0432\u0443\u0445 \u0441\u0442\u043E\u043B\u0431\u0446\u0430\u0445 \u043F\u0440\u0435\u043C\u0438\u0439 \u043D\u0435\u0442. \u0412 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0441\u0442\u0440\u043E\u043A\u0438 \u0447\u0451\u0442\u043D\u044B\u0445 \u0438 \u043D\u0435\u0447\u0451\u0442\u043D\u044B\u0445 \u0447\u0438\u0441\u0435\u043B \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u0443\u043C\u043C\u0443 \u0431\u0440\u043E\u0441\u043A\u0430, \u0435\u0441\u043B\u0438 \u0432\u0441\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u0438\u043C\u0435\u044E\u0442 \u043D\u0443\u0436\u043D\u0443\u044E \u0447\u0451\u0442\u043D\u043E\u0441\u0442\u044C. \u041F\u0440\u0438 \u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0439 \u043E\u0446\u0435\u043D\u043A\u0435 \u0442\u0440\u043E\u0439\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 20, \u043C\u0430\u043B\u044B\u0439 \u0441\u0442\u0440\u0438\u0442 \u2014 25, \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u2014 30, \u0444\u0443\u043B\u043B-\u0445\u0430\u0443\u0441 \u2014 35, \u043A\u0430\u0440\u0435 \u2014 40, \u043F\u044F\u0442\u044C \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u2014 50. \u0423\u0434\u0432\u043E\u0435\u043D\u0438\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u043D\u0435 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0432 \u0448\u043A\u043E\u043B\u0435. \u0412 \u0441\u0442\u0440\u043E\u0433\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0432 \u0448\u043A\u043E\u043B\u0435 \u043B\u0438\u0448\u0430\u0435\u0442 \u0438 \u0431\u0443\u0434\u0443\u0449\u0438\u0445 \u043F\u0440\u0435\u043C\u0438\u0439."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0430",
              "Enter \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0431\u0440\u043E\u0441\u043E\u043A. \u0426\u0438\u0444\u0440\u043E\u0439 \u043E\u0442 1 \u0434\u043E 6 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0434\u0438\u043D \u043A\u0443\u0431\u0438\u043A \u0441 \u0442\u0430\u043A\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0430. Shift \u0441 \u0442\u043E\u0439 \u0436\u0435 \u0446\u0438\u0444\u0440\u043E\u0439 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0432\u044B\u0431\u043E\u0440 \u043E\u0434\u043D\u043E\u0433\u043E \u043A\u0443\u0431\u0438\u043A\u0430. \u041F\u0440\u043E\u0431\u0435\u043B \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u0435\u0442 \u043A\u0443\u0431\u0438\u043A\u0438. \u041F\u043E\u0441\u043B\u0435 \u0431\u0440\u043E\u0441\u043A\u0430 Enter \u0431\u0435\u0437 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043F\u0438\u0441\u043E\u043A \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432. V \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0430\u0448\u0443 \u0442\u0430\u0431\u043B\u0438\u0446\u0443, Shift+V \u2014 \u0442\u0430\u0431\u043B\u0438\u0446\u0443 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430, \u0430 S \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u0443\u043C\u043C\u044B.")
          ]
        end
